import{d as r,C as s,o as g,c as d,a3 as t,E as e,j as a,a as h}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"正易心法·第二十三章","description":"《正易心法》第二十三章——古今传易，舛讹为多：论证履当在小畜之上（一柔变化序列、《龙图大衍》定数、反对义三重）与八体当为艮鼻巽手，是全书对传易文献的批评章。","frontmatter":{"title":"正易心法·第二十三章","description":"《正易心法》第二十三章——古今传易，舛讹为多：论证履当在小畜之上（一柔变化序列、《龙图大衍》定数、反对义三重）与八体当为艮鼻巽手，是全书对传易文献的批评章。","category":"guide","aliases":["正易心法第二十三章","古今传易舛讹为多","履畜八体"],"source":["《正易心法》"],"outline":[2,3]},"headers":[],"relativePath":"yijing/zheng-yi-xin-fa/chapter-23.md","filePath":"yijing/zheng-yi-xin-fa/chapter-23.md","lastUpdated":1790647676000}'),c={name:"yijing/zheng-yi-xin-fa/chapter-23.md"},x=r({...c,setup(u){const i=[{id:"z23-01",label:"一、舛讹为多",showLabel:!0,sentences:[["古今传易，",{text:"舛讹",glossary:"chuanE"},"为多。履畜八体，最为",{text:"害义",glossary:"haiyi"},"。"]],note:["古往今来传授《易》学，错误很多：其中履卦与小畜的卦序问题、以及八卦对应八体的问题，是最损害义理的错误。（这是全书的**文献批评章**——前二十二章用义理建立体系，本章用这个体系来检验传本。**「舛讹为多」四个字，是麻衣对传世文献的基本判断。**）"]},{id:"z23-02",label:"二、履先小畜",showLabel:!0,sentences:[["按卦序，当先履而后小畜。今小畜在先，则二卦画象反对，文义",{text:"缪乱",glossary:"miuluan"},"，而不可考。"]],note:["按照卦序，应当先是履卦、然后才是小畜。现在小畜排在前面，则这两卦的卦画象反对关系混乱，文义错乱，无法考证。（**履与小畜互为反卦**：履䷉（乾上兑下）翻转即得小畜䷈（巽上乾下）。按第十六章「反对」的原则，反卦应当相邻而有序——**先正后反（先履后小畜）**；今本颠倒，故曰「缪乱」。）"]},{id:"z23-03",label:"三、八体之误",showLabel:!0,sentences:[["又以八卦本对八体，独",{text:"阕其鼻",glossary:"queqibi"},"。乃以巽言",{text:"股",glossary:"gu"},"，股即系是也。若股可言，则又遗其肱，且与羲皇八卦不相应也。兹盖传者舛误耳，能不害义乎？"]],note:["又因为八卦本来对应人体八个部位，却唯独缺少了鼻子；于是用巽卦对应大腿。如果大腿可以说，那么又遗漏了手臂，而且与伏羲八卦不相应。这大概是传授者的错误，怎么能不损害义理呢？（今本《说卦传》作「巽为股，艮为手」——**有「股」（大腿）而无「鼻」，有「手」而失对待，身体既不完整、逻辑也混乱。**）"]},{id:"z23-04",label:"四、一柔一刚之序",showLabel:!0,sentences:[["试辨之，一柔自姤变同人，同人变履，履变小畜，小畜变大有，犹之一刚自复变师，又变谦，又变豫，又变比，皆自然之序不易也。今谦既在豫上，则知履不当在小畜下。"]],note:["试加以辨析：一柔自姤卦变化——姤变同人、同人变履、履变小畜、小畜变大有；正如一刚自复卦变化——复变师、又变谦、又变豫、又变比，都是自然的顺序，不可更改。现在谦卦既然在豫卦之前，就知道履卦不应当排在小畜之后。（**用「一柔」与「一刚」两条平行序列作类比**：既然「刚」的序列里谦在豫之前，那么「柔」的序列里履就应在小畜之前。**今本谦（第十五）在豫（第十六）之前是对的，而小畜（第九）在履（第十）之前就错了。**）"]},{id:"z23-05",label:"五、龙图定数",showLabel:!0,sentences:[["当密探",{text:"宣尼",glossary:"xuanni"},"述",{text:"九卦",glossary:"jiugua"},"，以履为用九，谦用十五，复用二十四，皆《",{text:"龙图大衍",glossary:"longtuDayan"},"》定数。则履在小畜上，为第九卦也明矣。"]],note:["应当仔细探究孔子所论述的九卦：以履为「用九」，谦用十五，复用二十四，都是《龙图大衍》的定数。那么履卦在小畜之上、为第九卦，就很清楚了。（孔子《系辞下》述九卦为「履、谦、复、恒、损、益、困、井、巽」。今本卦序中**谦正是第十五卦、复正是第二十四卦**——与定数吻合；**唯独履是第十卦，与「用九」不符。三个定数中两个已合，只有一个不合，这就是麻衣指出错位的那一个。**）"]},{id:"z23-06",label:"六、失其本真",showLabel:!0,sentences:[["又履与无妄对义，既以大畜反无妄而居下，则知小畜反履而居下无疑矣。今序卦非宣尼旨，失其本真也。"]],note:["又：履与无妄是对义关系；既然大畜作为无妄的反卦而排在无妄之后，那么小畜作为履的反卦而排在履之后，也就毫无疑问了。现在的《序卦传》不是孔子的本意，失去了原本的真实面目。（**三条论证并出：一柔序列的类比、《龙图大衍》定数、反对义关系。** 值得注意的是麻衣的分寸——**「今序卦非宣尼旨」：错的是传本，不是孔子。** 这与第四章「不得已而有辞」的立场一致。）"]},{id:"z23-07",label:"七、艮鼻巽手",showLabel:!0,sentences:[["八体，乃艮为鼻，巽为手耳。《传》曰：“鼻者，面之山也。”又曰：“风能鼓舞万物，而手之所以舞也。”"]],note:["八体应当是艮为鼻、巽为手。《传》说「鼻子是面部的山」（艮为山，鼻是面部最突出之处）；又说「风能鼓舞万物，而手正是用来舞动的」（巽为风，手最能动）。**这一改，八体就完整了：首、腹、耳、目、鼻、口、手、足——正是头面五官加躯干四肢。**）"]},{id:"z23-08",label:"八、八卦之应",showLabel:!0,sentences:[["盖乾为首，坤为腹，天地定位也。坎为耳，离为目，水火相逮也。艮为鼻，兑为口，山泽通气也。巽为手，震为足，雷风相薄也。此羲皇八卦之应矣，其理昭昭。"]],note:["乾为首、坤为腹——天地定位；坎为耳、离为目——水火相逮；艮为鼻、兑为口——山泽通气；巽为手、震为足——雷风相薄。这才是伏羲八卦与人体的对应，其道理昭然明白。（**四对全是先天八卦的「对待」关系**：乾坤（天地）、坎离（水火）、艮兑（山泽）、震巽（雷风）——**这就是麻衣判定的标准：八体对应必须符合先天八卦的对待结构。** 今本「巽为股、艮为手」恰恰破坏了这四对。）"]},{id:"z23-09",label:"九、承误效尤",showLabel:!0,sentences:[["但学者",{text:"承误效尤",glossary:"chengwuXiaoyou"},"，见不高远，其失至此。真人",{text:"闵",glossary:"min"},"之，故开其眼目。"]],note:["只是学者沿袭错误、效仿过失，见识不够高远，才造成这样的失误。真人怜悯这种情况，所以开启学者的眼界。（**「真人闵之，故开其眼目」是麻衣少见的自我指认**——在他看来这两个错误不是学术细枝末节，是「眼睛」的问题：**看错了，就什么都错了。**）"]}],l=[{id:"chuanE",term:"舛讹",pinyin:"chuǎn é",meaning:"错乱与讹误。舛是错乱，讹是错误。指传易过程中的错误。"},{id:"haiyi",term:"害义",pinyin:"hài yì",meaning:"损害义理。错误导致义理无法正确理解。"},{id:"miuluan",term:"缪乱",pinyin:"miù luàn",meaning:"混乱错误。缪通「谬」。"},{id:"queqibi",term:"阕其鼻",pinyin:"què qí bí",meaning:"唯独缺失了鼻子。阕是缺失。八体中鼻子被遗漏了。"},{id:"gu",term:"股",pinyin:"gǔ",meaning:"大腿。今本《说卦传》以巽为股，麻衣认为「股」有误（当为手）。"},{id:"xuanni",term:"宣尼",pinyin:"xuān ní",meaning:"孔子的字。汉平帝追谥孔子为「褒成宣尼公」，故称。"},{id:"jiugua",term:"九卦",pinyin:"jiǔ guà",meaning:"《系辞下》所述九卦：履、谦、复、恒、损、益、困、井、巽。麻衣据其定数校正卦序。"},{id:"longtuDayan",term:"龙图大衍",pinyin:"lóng tú dà yǎn",meaning:"河图与大衍之数的体系。麻衣所引的数理来源。"},{id:"chengwuXiaoyou",term:"承误效尤",pinyin:"chéng wù xiào yóu",meaning:"继承错误、效仿过失。后人沿袭前人的错误。"},{id:"min",term:"闵",pinyin:"mǐn",meaning:"怜悯、忧虑。「真人闵之」即麻衣怜悯这种情况。"}];return(b,n)=>{const o=s("DaoTextReading"),p=s("DaoKeywordCards");return g(),d("div",null,[n[0]||(n[0]=t("",24)),e(o,{colophon:"舛讹为多 · 履畜之序 · 八体正误 · 羲皇八卦之应",tone:"ink",density:"comfortable","default-mode":"slips","mode-switch":!0,"aria-label":"正易心法第二十三章原文",sections:i,glossary:l}),n[1]||(n[1]=a("blockquote",null,[a("p",null,"注：本页依所据底本录入。原文「一柔自姤变同人」「一刚自复变师」诸句及「龙图大衍」定数随底本，不作统一；本章所论为麻衣一家之说，读者可参看《系辞下》九卦与今本《说卦传》八体自行对勘。")],-1)),n[2]||(n[2]=a("h2",{id:"【原典层】字词释义",tabindex:"-1"},[h("【原典层】字词释义 "),a("a",{class:"header-anchor",href:"#【原典层】字词释义","aria-label":'Permalink to "【原典层】字词释义"'},"​")],-1)),e(p,{items:[{term:"舛讹",pinyin:["chuǎn","é"],meaning:"错乱与讹误。麻衣对传世文献的基本判断：「古今传易，舛讹为多」。"},{term:"履当在小畜上",pinyin:["lǚ","dāng"],meaning:"麻衣主张履为第九卦、小畜为第十卦，而今本相反。三重论证：一柔序列、龙图定数、反对义。"},{term:"龙图大衍定数",pinyin:["lóng","tú"],meaning:"履用九、谦用十五、复用二十四——今本谦与复皆合，唯履不合，故知履当在上。"},{term:"艮为鼻，巽为手",pinyin:["gèn","wéi"],meaning:"麻衣对《说卦传》八体的纠正。标准是先天八卦的四对对待：乾坤、坎离、艮兑、震巽。"},{term:"承误效尤",pinyin:["chéng","wù"],meaning:"继承错误、效仿过失。麻衣批评学者「见不高远，其失至此」。"}]}),n[3]||(n[3]=t("",26))])}}});export{y as __pageData,x as default};
